        fragmentShader: "\nvarying vec2 vUv;\nvarying vec3 vPos;\n\nfloat hash(vec3 p) {\n    p = fract(p * 0.3183099 + vec3(0.1, 0.2, 0.3));\n    p *= 17.0;\n    return fract(p.x * p.y * p.z * (p.x + p.y + p.z));\n}\n\nfloat noise(vec3 x) {\n    vec3 i = floor(x);\n    vec3 f = fract(x);\n    f = f * f * (3.0 - 2.0 * f);\n    return mix(\n        mix(mix(hash(i + vec3(0,0,0)), hash(i + vec3(1,0,0)), f.x),\n            mix(hash(i + vec3(0,1,0)), hash(i + vec3(1,1,0)), f.x), f.y),\n        mix(mix(hash(i + vec3(0,0,1)), hash(i + vec3(1,0,1)), f.x),\n            mix(hash(i + vec3(0,1,1)), hash(i + vec3(1,1,1)), f.x), f.y),\n        f.z);\n}\n\nfloat fbm(vec3 p) {\n    float v = 0.0;\n    float a = 0.5;\n    for (int i = 0; i < 3; i++) {\n        v += a * noise(p);\n        p *= 2.0;\n        a *= 0.5;\n    }\n    return v;\n}\n\nvoid main() {\n    // Colors sampled from your camo\n    vec3 c0 = vec3(0.15, 0.18, 0.09); // dark green\n    vec3 c1 = vec3(0.34, 0.40, 0.19); // shadow olive\n    vec3 c2 = vec3(0.44, 0.51, 0.26); // main green\n    vec3 c3 = vec3(0.66, 0.70, 0.47); // light sage\n\n    float scale = 1.5; // lower = bigger blobs\n    vec3 q = vPos * scale;\n\n    // domain warp gives the wavy, lobed edges\n    vec3 w = vec3(\n        noise(q * 2.0 + 3.1),\n        noise(q * 2.0 + 7.7),\n        noise(q * 2.0 + 1.3)\n    );\n    float p = fbm(q + (w - 0.5) * 0.9);\n\n    vec3 col;\n    if (p < 0.38)\n        col = c0;\n    else if (p < 0.47)\n        col = c1;\n    else if (p < 0.60)\n        col = c2;\n    else\n        col = c3;\n\n    gl_FragColor = vec4(col, 1.0);\n}\n"
